  double spacing=Math.Clamp(o.Spacing,40,240);if(light)spacing=Math.Max(120,spacing);int cols=(int)Math.Ceiling(w/spacing)+3,rows=(int)Math.Ceiling(h/spacing)+3;if(grid.Length<cols*rows)grid=new Vector2[cols*rows];long startX=(long)Math.Floor(-motion.X/spacing)-1,startY=(long)Math.Floor(-motion.Y/spacing)-1;for(int y=0;y<rows;y++)for(int x=0;x<cols;x++){double gx=startX+x,gy=startY+y,warp=spacing*.08*pulse;grid[y*cols+x]=new((float)(gx*spacing+motion.X+Math.Sin(gx*.71+gy*.93+time*.3)*warp),(float)(gy*spacing+motion.Y+Math.Cos(gx*.83-gy*.63+time*.3)*warp));}for(int y=0;y<rows-1;y++)for(int x=0;x<cols-1;x++){var p=grid[y*cols+x];Line(p,grid[y*cols+x+1],color,o.Line,w,h);Line(p,grid[(y+1)*cols+x],color,o.Line,w,h);Line(p,grid[(y+1)*cols+x+1],color,o.Line,w,h);}
